import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './navigation.css';

type Props = { selected: string; navigate: (id: string) => void; settings: () => void; help: () => void };
export function Navigation(p: Props) {
  return <nav aria-label="Primary navigation" className="kui-layout kui-sidebar navigation">
    <section className="kui-sidebar-section" aria-label="Workspace">
      <MenuHeader>Workspace</MenuHeader>
      <MenuItem selected={p.selected === 'overview'} aria-current={p.selected === 'overview' ? 'page' : undefined}
        icon={<span aria-hidden="true">⌂</span>} onClick={() => p.navigate('overview')}>Overview</MenuItem>
      <MenuItem selected={p.selected === 'projects'} aria-current={p.selected === 'projects' ? 'page' : undefined}
        onClick={() => p.navigate('projects')}>Projects</MenuItem>
    </section>
    <section className="kui-sidebar-section" aria-label="Organization">
      <MenuHeader>Organization</MenuHeader>
      <MenuItem selected={p.selected === 'people'} aria-current={p.selected === 'people' ? 'page' : undefined}
        icon={<span aria-hidden="true">♙</span>} onClick={() => p.navigate('people')}>People</MenuItem>
      <MenuItem disabled>Reports (unavailable)</MenuItem>
    </section>
    <section className="kui-sidebar-surface" aria-label="Workspace summary">
      <strong>Design workspace</strong>
      <p>12 projects · 8 members</p>
    </section>
    <footer className="navigation-footer" aria-label="Workspace actions">
      <MenuItem onClick={p.settings}>Settings</MenuItem>
      <MenuItem onClick={p.help}>Help</MenuItem>
    </footer>
  </nav>;
}

